function saveRating(bodyParams, enableRating) {
    const { recordedBlob, rating, feedback, device, browser, transcription_text, transcription_language, userId } = bodyParams;
    const formData = new FormData();
    formData.append('audio_data', recordedBlob);
    formData.append('rating', rating);
    formData.append('feedback', feedback);
    formData.append('device', device);
    formData.append('browser', browser);
    formData.append('text', transcription_text);
    formData.append('language', transcription_language);
    formData.append('user_id', userId);

    $.ajax({
        type: 'POST',
        url: 'api/feedback',
        data: formData,
        processData: false,
        contentType: false,
        beforeSend: function () {
            $("#loader").show();
        },
        success: function (data, textStatus, jqXHR) {
            $("#loader").hide();
        },
        error: function (jqXHR, textStatus, errorThrown) {
            $("#loader").hide();
            alert("Rating update failed, Please try again")
            enableRating(true)
            $('#Submit').attr("disabled", false);
        }
    });
}

function uploadFileToBatchService() {
    let files = document.querySelector('#audio_file_input').files;
    let blob = files[0];
    //let language = 'hi';
    let formData = new FormData();
    formData.append("audio_data", blob);
    formData.append("language", current_lang);
    formData.append("user", "");
    let filename = blob.name;
    $.ajax({
        type: 'POST',
        url: `/batch-service`,
        data: formData,
        contentType: false,
        processData: false,
        crossDomain: true,
        beforeSend: function () {
            // Show image container
            $('#file-loader').show();
        },
        success: function (response, textStatus, jqXHR) {
            const resp = response["data"];
            let a = document.createElement('a');
            let bl = new Blob([resp["srt"]], {'type': 'text/plain'});
            let url = window.URL.createObjectURL(bl);
            a.href = url;
            filename = filename.slice(0, filename.length - 4);
            a.download = filename+'.srt';
            a.click();
            window.URL.revokeObjectURL(url);
            $('#file-loader').hide();
        },
        error: function (jqXHR, textStatus, errorThrown) {
            alert('Failed: ' + textStatus);
            $('#file-loader').hide();
        }

    });
}

function punctuateText(textToPunctuate) {
    let formData = new FormData();
    formData.append("text", textToPunctuate);
    formData.append("enableITN", true);
    $.ajax({
        type: 'POST',
        url: `${URL}/v1/punctuate/${current_lang}`,
        data: formData,
        contentType: false,
        processData: false,
        crossDomain: true,
        beforeSend: function () {
            // Show image container
            $('#output-loader-icon').show();
        },
        success: function (response, textStatus, jqXHR) {
            const resp = response["data"];
            if(ENABLE_LOGS === true)
                console.log(resp['text']);
            $('#output-loader-icon').hide();
            if (resp['text'] !== null && resp['text'] !== undefined && resp['text'] !== 'null') {
                var element = angular.element(document.getElementById("output"));
                element.val(existingContent + " " + resp["text"]);
                element.triggerHandler('input');
                transcription_text = resp['text'];
            }
        },
        error: function (jqXHR, textStatus, errorThrown) {
            alert('Failed: ' + textStatus);
            $('#output-loader-icon').hide();
        }

    });
}

$(document).ready(function () {
    ss.forceBase64 = true;
    let pathname = window.location.pathname.replace("/ekstep/test", "").replace("/", "");
    if (pathname.length != 0) {
        // current_lang = fetchCurrentLanguageCode(pathname);
        current_lang = "en_bio"
        let titleLanguage = toCamelCase(pathname);
        if (pathname === "indian-english")
            titleLanguage = "English(IN)";
        else if (pathname === "kannada-lm")
            titleLanguage = "Kannada (With LM)";
        document.getElementById("title-text").innerHTML = titleLanguage + " Speech Recognition Model"
    }

    device = getDeviceInfo();
    browser = getBrowserInfo();
    $('#Submit').on('click', function () {
        event.preventDefault();
        $('.active').removeClass('active');
        $(this).addClass('active');
        stopRecording();
        rating = $('[name="star"]:checked').val();
        feedback = $("#feedback-dropdown").val();
        enableRating(false)
        saveRating({
            recordedBlob,
            rating,
            feedback,
            device,
            browser,
            transcription_text,
            transcription_language,
            userId
        }, enableRating);
    });
    enableRating(false);
    $('input[type=radio][name=star]').change(function () {
        if(ENABLE_LOGS === true)
            console.log($(this).val())
        if ($(this).val() >= 1) {
            $('select').prop("disabled", false)
            $('#Submit').attr("disabled", false)
        } else {
            $('select').prop("disabled", true)
            $('#Submit').attr("disabled", true)
        }
    });
});

